class Solution:
    def pacific_atlantic_flow(self, grid):
        """Find all cells where water can flow to both Pacific and Atlantic oceans.

        Uses boundary DFS starting from ocean borders and flowing inland
        to neighbors with height >= current (reverse flow direction).

        Args:
            grid: m x n matrix of non-negative integers representing land heights

        Returns:
            List of [row, col] coordinates reachable from both oceans
        """
        if not grid or not grid[0]:
            return []

        rows, cols = len(grid), len(grid[0])
        pacific_reachable = set()
        atlantic_reachable = set()

        def dfs(r, c, reachable):
            reachable.add((r, c))
            for dr, dc in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    if (nr, nc) not in reachable and grid[nr][nc] >= grid[r][c]:
                        dfs(nr, nc, reachable)

        # DFS from Pacific borders (top row and left column)
        for r in range(rows):
            dfs(r, 0, pacific_reachable)
        for c in range(cols):
            dfs(0, c, pacific_reachable)

        # DFS from Atlantic borders (bottom row and right column)
        for r in range(rows):
            dfs(r, cols - 1, atlantic_reachable)
        for c in range(cols):
            dfs(rows - 1, c, atlantic_reachable)

        # Return intersection of both sets
        return list(pacific_reachable & atlantic_reachable)
